mapper.update:
UPDATE allocation_execution SET claim_epoch=claim_epoch+1,lease_until=#{lease},updated_at=#{now}
WHERE enterprise_id=#{e} AND attempt_id=#{a} AND claim_epoch=#{epoch}
AND (lease_until IS NULL OR lease_until<=#{now})

UPDATE allocation_execution SET xid=#{row.xid},empty_xid=#{row.empty_xid},state=#{row.state},requested_action=#{row.requested_action},
next_warehouse=#{row.next_warehouse},rpc_attempts=#{row.rpc_attempts},next_at=#{row.next_at},error_code=#{row.error_code},
terminal_evidence=#{row.terminal_evidence},lease_until=#{row.lease_until},updated_at=#{now}
WHERE enterprise_id=#{row.enterprise_id} AND attempt_id=#{row.attempt_id} AND claim_epoch=#{epoch}
AND (xid IS NULL OR xid=#{row.xid}) AND (requested_action IS NULL OR requested_action=#{row.requested_action})
